const IMPORT_LIMIT: u64 = 8 * 1024 * 1024 * 1024;
const COPY_BUFFER_SIZE: usize = 64 * 1024;
const SEALED_STAGING_VERSION: u8 = 1;
const PHASE_AUTHENTICATED_EXPORT_INTENT_VERSION: u8 = 2;
const EXACT_EXPORT_INTENT_VERSION: u8 = 3;

fn deserialize_omittable_non_null<'de, D, T>(
    deserializer: D,
) -> std::result::Result<Option<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    T::deserialize(deserializer).map(Some)
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Sensitivity {
    Public,
    Local,
    Private,
    Confidential,
    Secret,
}

impl Sensitivity {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Public => "public",
            Self::Local => "local",
            Self::Private => "private",
            Self::Confidential => "confidential",
            Self::Secret => "secret",
        }
    }

    pub(super) fn parse(value: &str) -> Result<Self> {
        serde_json::from_value(serde_json::Value::String(value.to_owned())).map_err(Into::into)
    }

    fn propagation_rank(&self) -> u8 {
        match self {
            Self::Public => 0,
            Self::Local => 1,
            Self::Private => 2,
            Self::Confidential => 3,
            Self::Secret => 4,
        }
    }
}

