#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ContentHash {
    pub algorithm: String,
    pub value: String,
}

impl ContentHash {
    fn from_tagged(tagged: &str) -> Result<Self> {
        let value = tagged
            .strip_prefix("sha256:")
            .ok_or(TaskManagerError::InvalidRecord(
                "stored Artifact content hash is not canonical SHA-256",
            ))?;
        if value.len() != 64
            || !value
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        {
            return Err(TaskManagerError::InvalidRecord(
                "stored Artifact content hash is not canonical SHA-256",
            ));
        }
        Ok(Self {
            algorithm: "sha256".to_owned(),
            value: value.to_owned(),
        })
    }

    pub fn tagged(&self) -> String {
        format!("{}:{}", self.algorithm, self.value)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(transparent)]
pub struct ArtifactUri(String);

impl ArtifactUri {
    pub fn as_str(&self) -> &str {
        &self.0
    }

    fn new(artifact_id: &str) -> Self {
        Self(format!("artifact://{artifact_id}"))
    }
}

impl<'de> Deserialize<'de> for ArtifactUri {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let value = String::deserialize(deserializer)?;
        if ![
            "artifact://",
            "data://",
            "stream://",
            "model://",
            "secret://",
        ]
        .iter()
        .any(|scheme| value.starts_with(scheme))
        {
            return Err(serde::de::Error::custom("invalid Artifact URI scheme"));
        }
        Ok(Self(value))
    }
}

