    #[allow(
        clippy::too_many_lines,
        reason = "builds the full synthetic binding and grant rows for authority fixture tests"
    )]
    fn install_one_shot_binding_with_issuance(
        manager: &TaskManager,
        fixture: &str,
        input_artifact_ids: &[String],
        operations: &[(&str, &str, &str)],
        issue_receipts: bool,
    ) -> (String, String) {
        let program_hash = allocation("unused").semantic_program_hash;
        let registry_id = format!("registry-{fixture}");
        let policy_id = format!("policy-{fixture}");
        let binding_id = format!("binding-{fixture}");
        let attempt_id = format!("attempt-{fixture}");
        let request_ids = (0..operations.len())
            .map(|index| format!("request-{fixture}-{index}"))
            .collect::<Vec<_>>();
        let decision_ids = (0..operations.len())
            .map(|index| format!("decision-{fixture}-{index}"))
            .collect::<Vec<_>>();
        let grant_ids = (0..operations.len())
            .map(|index| format!("grant-{fixture}-{index}"))
            .collect::<Vec<_>>();
        manager
            .connection
            .execute(
                "INSERT INTO registry_snapshots(snapshot_id,manifest_json,created_at) VALUES (?1,'{}','2026-09-19T00:00:00Z')",
                [&registry_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO semantic_program_revisions(task_id,program_revision,program_id,ir_version,semantic_hash,registry_snapshot_id,status,program_json,created_at) VALUES ('T-artifact',1,?1,'0.1',?2,?3,'active','{\"nodes\":[{\"id\":\"compose_report\"}]}','2026-09-19T00:00:00Z')",
                params![format!("program-{fixture}"), program_hash, registry_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE tasks SET state='RUNNING',active_program_revision=1,active_step_ids_json='[\"compose_report\"]' WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO execution_bindings(binding_id,attempt_id,task_id,semantic_program_hash,registry_snapshot_id,ir_version,node_id,capability,provider_id,provider_version,attempt,policy_decision_refs_json,grant_refs_json,execution_profile_ref,placement_json,binding_json,created_at) VALUES (?1,?2,'T-artifact',?3,?4,'0.1','compose_report','document.compose','provider:sequential','1',1,?5,?6,'profile:test','{}','{}','2026-09-19T00:00:00Z')",
                params![
                    binding_id,
                    attempt_id,
                    program_hash,
                    registry_id,
                    serde_json::to_string(&decision_ids).unwrap(),
                    serde_json::to_string(&grant_ids).unwrap()
                ],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO step_executions(attempt_id,task_id,semantic_program_hash,registry_snapshot_id,node_id,binding_id,attempt_number,revision,state,input_artifacts_json,output_artifacts_json,created_at,updated_at) VALUES (?1,'T-artifact',?2,?3,'compose_report',?4,1,1,'RUNNING',?5,'[]','2026-09-19T00:00:00Z','2026-09-19T00:00:00Z')",
                params![
                    attempt_id,
                    program_hash,
                    registry_id,
                    binding_id,
                    serde_json::to_string(input_artifact_ids).unwrap()
                ],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO policy_snapshots(snapshot_id,scope_kind,scope_id,policy_language,policy_set_hash,engine_id,engine_version,snapshot_json,created_at) VALUES (?1,'task','T-artifact','cedar','sha256:policy','test','1','{}','2026-09-19T00:00:00Z')",
                [&policy_id],
            )
            .unwrap();

        for (index, (action, resource_kind, resource_id)) in operations.iter().enumerate() {
            manager
                .connection
                .execute(
                    "INSERT INTO authority_requests(request_id,task_id,semantic_program_hash,registry_snapshot_id,node_id,capability,principal_kind,principal_id,execution_binding_id,attempt_id,action,resolved_resource_kind,resolved_resource_id,semantic_selector,request_json,requested_at) VALUES (?1,'T-artifact',?2,?3,'compose_report','document.compose','provider','provider:sequential',?4,?5,?6,?7,?8,'fixture','{}','2026-09-19T00:00:00Z')",
                    params![request_ids[index], program_hash, registry_id, binding_id, attempt_id, action, resource_kind, resource_id],
                )
                .unwrap();
            manager
                .connection
                .execute(
                    "INSERT INTO policy_decisions(decision_id,authority_request_id,task_id,semantic_program_hash,node_id,principal_kind,principal_id,action,resolved_resource_kind,resolved_resource_id,decision,policy_snapshot_id,reason_codes_json,decision_json,decided_at) VALUES (?1,?2,'T-artifact',?3,'compose_report','provider','provider:sequential',?4,?5,?6,'ALLOW',?7,'[]','{}','2026-09-19T00:00:00Z')",
                    params![decision_ids[index], request_ids[index], program_hash, action, resource_kind, resource_id, policy_id],
                )
                .unwrap();
            let grants = json!([{
                "action": action,
                "resource_kind": resource_kind,
                "resource_id": resource_id,
                "semantic_selector": "fixture"
            }]);
            manager
                .connection
                .execute(
                    "INSERT INTO authority_grants(grant_id,task_id,semantic_program_hash,node_id,capability,principal_kind,principal_id,execution_binding_id,attempt_id,policy_decision_id,policy_snapshot_id,grants_json,scope,max_uses,uses_consumed,state,issued_at,expires_at) VALUES (?1,'T-artifact',?2,'compose_report','document.compose','provider','provider:sequential',?3,?4,?5,?6,?7,'ONE_SHOT',1,0,'ACTIVE','2026-09-19T00:00:00Z','2026-09-20T00:00:00Z')",
                    params![grant_ids[index], program_hash, binding_id, attempt_id, decision_ids[index], policy_id, grants.to_string()],
                )
                .unwrap();
            if issue_receipts {
                crate::admit_fixture_grant(&manager.connection, &grant_ids[index]).unwrap();
            }
        }
        (binding_id, attempt_id)
    }

    fn install_one_shot_binding(
        manager: &TaskManager,
        fixture: &str,
        input_artifact_ids: &[String],
        operations: &[(&str, &str, &str)],
    ) -> (String, String) {
        install_one_shot_binding_with_issuance(
            manager,
            fixture,
            input_artifact_ids,
            operations,
            true,
        )
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "keeps the complete approval binding and retained-reader chronology visible in one regression"
    )]
    fn withdrawn_bound_approval_fences_artifact_reader_without_mutating_grant() {
        use crate::authority_policy::AuthenticatedApprover;

        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"approval-backed input".as_slice()),
            )
            .unwrap();
        let fixture = "withdrawn-approval-read";
        let (binding_id, _) = install_one_shot_binding_with_issuance(
            &manager,
            fixture,
            std::slice::from_ref(&artifact.artifact_id),
            &[("artifact.read", "artifact", &artifact.artifact_id)],
            false,
        );
        let approval_id = "approval-withdrawn-artifact-read";
        let request_id = format!("request-{fixture}-0");
        let decision_id = format!("decision-{fixture}-0");
        let grant_id = format!("grant-{fixture}-0");
        let program_hash = allocation("unused").semantic_program_hash;
        manager
            .connection
            .execute(
                "UPDATE authority_grants SET scope='TASK',max_uses=NULL WHERE grant_id=?1",
                [&grant_id],
            )
            .unwrap();
        crate::admit_fixture_grant(&manager.connection, &grant_id).unwrap();

        // A bound 0017 approval requires a pending request and its exact
        // REQUIRE_APPROVAL evaluation before the APPROVE decision is recorded.
        manager
            .connection
            .execute_batch(
                "INSERT INTO provider_registrations(registration_id,provider_id,provider_version,
                manifest_hash,package_content_hash,registry_snapshot_id,state,trust_status,
                registration_json,registered_at)
             VALUES ('registration:withdrawn-read','provider:sequential','1',
                'manifest:withdrawn-read','package:withdrawn-read',
                'registry-withdrawn-approval-read','registered','trusted','{}',
                '2026-09-19T00:00:00Z');
             INSERT INTO provider_conformance_evidence(evidence_id,registration_id,capability,
                contract_hash,status,evidence_json,tested_at)
             VALUES ('evidence:withdrawn-read','registration:withdrawn-read','document.compose',
                'contract:withdrawn-read','passed','{}','2026-09-19T00:00:00Z');
             INSERT INTO authority_policy_payloads(content_hash,policy_json,created_at)
             VALUES ('policy:withdrawn-read','{}','2026-09-19T00:00:00Z');
             INSERT INTO authority_policy_activations(revision,content_hash,activated_at)
             VALUES (1,'policy:withdrawn-read','2026-09-19T00:00:00Z');",
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO authority_candidate_reservations(candidate_id,binding_id,attempt_id,
                task_id,semantic_program_hash,registry_snapshot_id,ir_version,node_id,
                capability,capability_contract_hash,provider_registration_id,provider_id,
                provider_version,provider_manifest_hash,provider_build_hash,
                conformance_evidence_id,provider_trust_source_id,execution_profile_ref,
                isolation_class,placement_locality,attempt_number,resource_count,created_at)
             VALUES ('candidate:withdrawn-read','binding:candidate-withdrawn-read',
                'attempt:candidate-withdrawn-read','T-artifact',?1,
                'registry-withdrawn-approval-read','0.1','compose_report','document.compose',
                'contract:withdrawn-read','registration:withdrawn-read','provider:sequential',
                '1','manifest:withdrawn-read','build:withdrawn-read',
                'evidence:withdrawn-read','trust:withdrawn-read','profile:test','P1','local',2,
                1,'2026-09-19T00:00:00Z')",
                [&program_hash],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO authority_candidate_resources(candidate_id,action,semantic_selector,
                resource_kind,resource_id,output_port,expected_semantic_type)
             VALUES ('candidate:withdrawn-read','artifact.read','fixture','artifact',?1,
                NULL,'artifact.table@1')",
                [&artifact.artifact_id],
            )
            .unwrap();
        manager
            .connection
            .execute_batch(
                "INSERT INTO authority_candidate_status(candidate_id,revision,state,updated_at)
             VALUES ('candidate:withdrawn-read',1,'PENDING','2026-09-19T00:00:00Z');",
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO approval_requests(approval_id,authority_request_id,task_id,
                semantic_program_hash,node_id,action,status,request_json,created_at,expires_at)
             VALUES (?1,?2,'T-artifact',?3,'compose_report','artifact.read','PENDING',
                '{}','2026-09-19T00:00:00Z','2026-09-20T00:00:00Z')",
                params![approval_id, request_id, program_hash],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO policy_decisions(decision_id,authority_request_id,task_id,
                semantic_program_hash,node_id,principal_kind,principal_id,action,
                resolved_resource_kind,resolved_resource_id,decision,policy_snapshot_id,
                approval_request_id,reason_codes_json,decision_json,decided_at)
             VALUES ('decision:requiring-withdrawn-read',?1,'T-artifact',?2,
                'compose_report','provider','provider:sequential','artifact.read',
                'artifact',?3,'REQUIRE_APPROVAL','policy-withdrawn-approval-read',?4,
                '[]','{}','2026-09-19T00:00:00Z')",
                params![request_id, program_hash, artifact.artifact_id, approval_id],
            )
            .unwrap();
        manager
            .connection
            .execute_batch(
                "INSERT INTO authority_evaluation_fingerprints(decision_id,candidate_id,
                fingerprint,activation_revision,evaluated_at)
             VALUES ('decision:requiring-withdrawn-read','candidate:withdrawn-read',
                'fingerprint:withdrawn-read',1,'2026-09-19T00:00:00Z');",
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO authority_approval_bindings(approval_id,candidate_id,fingerprint,
                activation_revision,requiring_decision_id)
             VALUES (?1,'candidate:withdrawn-read','fingerprint:withdrawn-read',1,
                'decision:requiring-withdrawn-read')",
                [approval_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "INSERT INTO approval_decisions(decision_id,approval_id,task_id,decision,
                decided_by_kind,decided_by_id,scope,approved_until,decision_json,decided_at)
             VALUES ('approval-decision:withdrawn-read',?1,'T-artifact','APPROVE',
                'user','user:test','TASK','2026-09-20T00:00:00Z','{}',
                '2026-09-19T00:00:00Z')",
                [approval_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE approval_requests SET status='APPROVED' WHERE approval_id=?1",
                [approval_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE policy_decisions SET approval_request_id=?2 WHERE decision_id=?1",
                params![decision_id, approval_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE authority_grants SET approval_id=?2 WHERE grant_id=?1",
                params![grant_id, approval_id],
            )
            .unwrap();

        let scope = scope_bound_reads(
            &manager,
            "T-artifact",
            &binding_id,
            std::slice::from_ref(&artifact.artifact_id),
        )
        .unwrap();
        let mut reader = manager
            .open_artifact_reader(&scope, &artifact.artifact_id)
            .unwrap();
        let mut first_byte = [0_u8; 1];
        assert_eq!(reader.read(&mut first_byte).unwrap(), 1);
        assert_eq!(first_byte[0], b'a');
        assert_eq!(reader.seek(SeekFrom::Start(0)).unwrap(), 0);
        let grant_before: (String, i64, Option<String>) = manager
            .connection
            .query_row(
                "SELECT state,uses_consumed,revoked_at FROM authority_grants WHERE grant_id=?1",
                [&grant_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(grant_before, ("ACTIVE".to_owned(), 0, None));
        // The retained scope is still usable immediately before withdrawal.
        assert_eq!(reader.read(&mut first_byte).unwrap(), 1);
        let fresh_scope = scope_bound_reads(
            &manager,
            "T-artifact",
            &binding_id,
            std::slice::from_ref(&artifact.artifact_id),
        )
        .unwrap();
        assert!(
            manager
                .open_artifact_reader(&fresh_scope, &artifact.artifact_id)
                .is_ok()
        );

        manager
            .revoke_candidate_approval(
                approval_id,
                &AuthenticatedApprover {
                    principal_id: "user:test",
                },
            )
            .unwrap();
        let (status, decision, grant_state, revoked_at): (String, String, String, Option<String>) =
            manager
                .connection
                .query_row(
                    "SELECT a.status,d.decision,g.state,b.revoked_at
                 FROM approval_requests a JOIN approval_decisions d USING(approval_id)
                 JOIN authority_grants g ON g.approval_id=a.approval_id
                 JOIN authority_approval_bindings b USING(approval_id)
                 WHERE a.approval_id=?1",
                    [approval_id],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
                )
                .unwrap();
        assert_eq!(
            (status.as_str(), decision.as_str(), grant_state.as_str()),
            ("APPROVED", "APPROVE", "ACTIVE")
        );
        assert!(revoked_at.is_some());
        let grant_after: (String, i64, Option<String>) = manager
            .connection
            .query_row(
                "SELECT state,uses_consumed,revoked_at FROM authority_grants WHERE grant_id=?1",
                [&grant_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(grant_after, grant_before);
        assert!(matches!(
            scope_bound_reads(
                &manager,
                "T-artifact",
                &binding_id,
                std::slice::from_ref(&artifact.artifact_id)
            ),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        assert!(matches!(
            manager.open_artifact_reader(&scope, &artifact.artifact_id),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        assert_eq!(
            reader.read(&mut first_byte).unwrap_err().kind(),
            std::io::ErrorKind::PermissionDenied
        );
        assert_eq!(
            reader.seek(SeekFrom::Start(0)).unwrap_err().kind(),
            std::io::ErrorKind::PermissionDenied
        );
    }

    #[test]
    fn sql_seeded_grant_without_issuance_cannot_read_artifact() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"legacy authority fixture".as_slice()),
            )
            .unwrap();
        let (binding_id, _) = install_one_shot_binding_with_issuance(
            &manager,
            "unissued-read",
            &[artifact.artifact_id.clone()],
            &[("artifact.read", "artifact", &artifact.artifact_id)],
            false,
        );
        manager
            .connection
            .execute(
                "UPDATE authority_grants SET token_id='fixture:manual-sql' WHERE grant_id='grant-unissued-read-0'",
                [],
            )
            .unwrap();
        assert!(matches!(
            scope_bound_reads(&manager, "T-artifact", &binding_id, &[artifact.artifact_id]),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
    }

    #[allow(
        clippy::too_many_lines,
        reason = "builds a complete provenance-authenticated running Task fixture"
    )]
    fn authenticate_running_fixture_history(manager: &mut TaskManager, task_id: &str) {
        manager
            .connection
            .execute(
                "UPDATE tasks SET revision=1,state='CREATED',active_step_ids_json='[]',
                 state_reason_json=(SELECT event_json FROM provenance_events
                    WHERE task_id=?1 AND event_type='task.created' LIMIT 1)
                 WHERE task_id=?1",
                [task_id],
            )
            .unwrap();
        let active_program = manager
            .connection
            .query_row(
                "SELECT program_id,ir_version,semantic_hash,registry_snapshot_id,program_json
                 FROM semantic_program_revisions
                 WHERE task_id=?1 AND program_revision=1",
                [task_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                        row.get::<_, String>(3)?,
                        row.get::<_, String>(4)?,
                    ))
                },
            )
            .optional()
            .unwrap();
        let active_program = active_program.map(
            |(program_id, ir_version, semantic_hash, registry_snapshot_id, program_json)| {
                json!({
                    "program_id": program_id,
                    "ir_version": ir_version,
                    "semantic_hash": semantic_hash,
                    "registry_snapshot_id": registry_snapshot_id,
                    "validation_result_id": null,
                    "validated_at": null,
                    "validator_id": null,
                    "validator_version": null,
                    "program_content_digest": super::super::program_content_digest(&program_json).unwrap(),
                })
            },
        );
        let transaction = manager.connection.transaction().unwrap();
        let mut from = crate::TaskState::Created;
        for (index, to) in [
            crate::TaskState::Planning,
            crate::TaskState::Runnable,
            crate::TaskState::Running,
        ]
        .into_iter()
        .enumerate()
        {
            let previous_revision = i64::try_from(index + 1).unwrap();
            let new_revision = previous_revision + 1;
            let event = json!({
                "schema_version": SCHEMA_VERSION,
                "event_id": format!("event:fixture-running:{task_id}:{new_revision}"),
                "task_id": task_id,
                "event_type": "task.transitioned",
                "timestamp": "2026-09-19T22:00:00Z",
                "actor": {"kind":"system-service","id":"service:test"},
                "status": "success",
                "semantic_program_hash": active_program.as_ref().and_then(|value| value.get("semantic_hash")),
                "ir_version": active_program.as_ref().and_then(|value| value.get("ir_version")),
                "registry_snapshot_id": active_program.as_ref().and_then(|value| value.get("registry_snapshot_id")),
                "validation_result_id": null,
                "task_transition": {
                    "transition_id": format!("fixture-running:{task_id}:{new_revision}"),
                    "previous_state": from,
                    "new_state": to,
                    "previous_revision": previous_revision,
                    "new_revision": new_revision,
                    "reason_code": "STATE_CHANGE_REQUESTED"
                },
                "committed_mutation": {
                    "active_plan": null,
                    "active_step_ids": if index == 0 { json!(["compose_report"]) } else { serde_json::Value::Null },
                    "waiting_on": null,
                    "failure": null,
                    "recovery": null
                },
                "details": {
                    "related_ids": [],
                    "reason_message_ref": null,
                    "active_program": active_program,
                    "mutation_text_commitments": {"waiting_on":null,"failure_summary":null}
                }
            });
            let appended = append_event(&transaction, task_id, &event).unwrap();
            transaction
                .execute(
                    "UPDATE tasks SET revision=?2,state=?3,
                     active_step_ids_json='[\"compose_report\"]',updated_at=?4,
                     state_reason_json=?5 WHERE task_id=?1",
                    params![
                        task_id,
                        new_revision,
                        to.as_str(),
                        "2026-09-19T22:00:00Z",
                        json!({"code":"STATE_CHANGE_REQUESTED","message":null,"provenance_event_id":appended.event_id}).to_string()
                    ],
                )
                .unwrap();
            from = to;
        }
        transaction.commit().unwrap();
    }

    fn publication(id: &str, allocation_id: &str) -> ArtifactPublicationRequest {
        ArtifactPublicationRequest {
            schema_version: "0.1".to_owned(),
            publication_id: id.to_owned(),
            allocation_id: allocation_id.to_owned(),
            task_id: "T-artifact".to_owned(),
            expected_allocation_state: ArtifactExpectedState::Writing,
            semantic_type: Some("artifact.report@1".to_owned()),
            media_type: "text/markdown".to_owned(),
            format: Some("markdown".to_owned()),
            lineage: ArtifactLineage::default(),
            labels: vec!["fixture".to_owned()],
        }
    }

    fn write_output(manager: &mut TaskManager, allocation_id: &str, bytes: &[u8]) {
        let mut writer = manager.open_artifact_output(allocation_id).unwrap();
        writer.write_all(bytes).unwrap();
        assert_eq!(writer.finish().unwrap(), bytes.len() as u64);
    }

    fn finish_bound_output(
        manager: &mut TaskManager,
        fixture: &str,
        scope: &str,
    ) -> (String, String) {
        let allocation_id = format!("alloc-{fixture}");
        let (binding_id, attempt_id) = install_one_shot_binding(
            manager,
            fixture,
            &[],
            &[("artifact.write", "output-allocation", &allocation_id)],
        );
        let grant_id = format!("grant-{fixture}-0");
        manager
            .connection
            .execute(
                "UPDATE authority_grants SET scope=?1 WHERE grant_id=?2",
                params![scope, grant_id],
            )
            .unwrap();
        let mut request = allocation(&allocation_id);
        request.binding_id = Some(binding_id);
        request.attempt_id = Some(attempt_id);
        allocate_bound(manager, &request);
        let mut writer = open_bound(manager, &allocation_id);
        writer.write_all(fixture.as_bytes()).unwrap();
        writer.finish().unwrap();
        (allocation_id, grant_id)
    }

