    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "covers exact egress admission, transfer provenance, and authenticated replay"
    )]
    fn provider_export_requires_exact_destination_grant_and_records_typed_transfer() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"exported bytes".as_slice()),
            )
            .unwrap();
        let (binding_id, _) = install_one_shot_binding(
            &manager,
            "export-authorized",
            std::slice::from_ref(&artifact.artifact_id),
            &[
                ("artifact.read", "artifact", &artifact.artifact_id),
                ("data.egress", "destination", "user-selected-file"),
            ],
        );
        let session = manager
            .issue_provider_artifact_session("T-artifact", &binding_id)
            .unwrap();
        let scope = manager
            .scope_artifact_reads(&session, std::slice::from_ref(&artifact.artifact_id))
            .unwrap();
        assert!(matches!(
            manager.issue_legacy_fixture_artifact_export_destination(
                &session,
                &scope,
                "export-operation-wrong-destination",
                &artifact.artifact_id,
                "remote-model",
                1_024,
                deferred(Vec::new()),
            ),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        let captured = Arc::new(Mutex::new(Vec::new()));
        let mut destination = manager
            .issue_legacy_fixture_artifact_export_destination(
                &session,
                &scope,
                "export-operation-authorized",
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(CapturedExportWriter(Arc::clone(&captured))),
            )
            .unwrap();
        assert_eq!(
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut destination)
                .unwrap(),
            14
        );
        assert!(destination.writer.is_none());
        assert_eq!(*captured.lock().unwrap(), b"exported bytes");
        assert_eq!(
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut destination)
                .unwrap(),
            14
        );
        assert!(destination.writer.is_none());
        assert_eq!(*captured.lock().unwrap(), b"exported bytes");
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT uses_consumed FROM authority_grants WHERE grant_id='grant-export-authorized-1'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
        let stored_event: serde_json::Value = serde_json::from_str(
            &manager
                .connection
                .query_row(
                    "SELECT event_json FROM provenance_events WHERE task_id='T-artifact' AND event_type='artifact.exported'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
        )
        .unwrap();
        assert_eq!(
            stored_event["external_transfer"],
            json!({
                "destination":"user-selected-file",
                "data_refs":[artifact.artifact_id],
                "purpose":null,
            })
        );
        assert_eq!(
            stored_event["authority_token_id"],
            "grant-export-authorized-1"
        );
        assert_eq!(
            stored_event["details"]["operation_id"],
            "export-operation-authorized"
        );
        assert_matches_schema("provenance-event.schema.json", &stored_event);
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state || ':' || outcome_certainty FROM operations WHERE operation_id='export-operation-authorized'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "SUCCEEDED:COMPLETED"
        );
    }

    #[test]
    fn successful_export_disposes_effectful_writer_under_fresh_guarded_marker() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"dispose me".as_slice()),
            )
            .unwrap();
        let scope = manager
            .scope_owned_artifact_reads("T-artifact", std::slice::from_ref(&artifact.artifact_id))
            .unwrap();
        let bytes = Arc::new(Mutex::new(Vec::new()));
        let drops = Arc::new(AtomicUsize::new(0));
        let guarded_drops = Arc::new(AtomicUsize::new(0));
        let state_at_drop = Arc::new(Mutex::new(None));
        let writer = EffectfulDropWriter {
            bytes: Arc::clone(&bytes),
            drops: Arc::clone(&drops),
            guarded_drops: Arc::clone(&guarded_drops),
            callback_active: Arc::clone(&manager.artifact_export_callback_active),
            database,
            operation_id: "export-effectful-dispose-success".to_owned(),
            state_at_drop: Arc::clone(&state_at_drop),
        };
        let mut destination = manager
            .issue_owned_artifact_export_destination(
                &scope,
                "export-effectful-dispose-success",
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(writer),
            )
            .unwrap();
        assert_eq!(
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut destination)
                .unwrap(),
            10
        );
        assert_eq!(*bytes.lock().unwrap(), b"dispose me!");
        assert!(destination.writer.is_none());
        assert_eq!(drops.load(Ordering::SeqCst), 1);
        assert_eq!(guarded_drops.load(Ordering::SeqCst), 1);
        assert_eq!(state_at_drop.lock().unwrap().as_deref(), Some("STARTED"));
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT COUNT(DISTINCT p.marker_id) FROM trusted_time_effect_resolutions r
                     JOIN trusted_time_effect_preparations p USING(marker_id)
                     WHERE p.subject_kind='ARTIFACT_EXPORT_FINALIZE'
                       AND p.subject_id='export-effectful-dispose-success'
                       AND r.resolution_kind='EFFECT_INVOKED'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            2,
            "finalization and disposal have separate durable markers"
        );
        drop(destination);
        assert_eq!(drops.load(Ordering::SeqCst), 1);
    }

