    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "table-driven tampering covers every previously spot-checked export event field"
    )]
    fn completed_export_replay_authenticates_the_complete_expected_event() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"event exact".as_slice()),
            )
            .unwrap();
        let scope = manager
            .scope_owned_artifact_reads("T-artifact", std::slice::from_ref(&artifact.artifact_id))
            .unwrap();
        let operation_id = "export-complete-event-proof";
        let mut destination = manager
            .issue_owned_artifact_export_destination(
                &scope,
                operation_id,
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(Vec::new()),
            )
            .unwrap();
        manager
            .export_artifact(&scope, &artifact.artifact_id, &mut destination)
            .unwrap();
        let original_event_id = event_id("artifact-exported", operation_id);
        let (sequence, previous_hash, original_event_json) = manager
            .connection
            .query_row(
                "SELECT sequence,previous_event_hash,event_json FROM provenance_events
                 WHERE event_id=?1",
                [&original_event_id],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )
            .unwrap();
        let original_receipt = manager
            .connection
            .query_row(
                "SELECT external_receipt FROM operations WHERE operation_id=?1",
                [operation_id],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        manager
            .connection
            .execute_batch("DROP TRIGGER provenance_events_no_update")
            .unwrap();

        for scenario in [
            "event-id",
            "semantic-program",
            "step",
            "provider",
            "status",
            "outputs",
            "data-refs",
            "purpose",
        ] {
            let mut event: serde_json::Value = serde_json::from_str(&original_event_json).unwrap();
            let stored_event_id = if scenario == "event-id" {
                event["event_id"] = json!("event:artifact-exported:forged");
                "event:artifact-exported:forged"
            } else {
                match scenario {
                    "semantic-program" => {
                        event["semantic_program_hash"] = json!(
                            "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                        );
                    }
                    "step" => event["step_id"] = json!("step:forged"),
                    "provider" => event["provider_id"] = json!("provider:forged"),
                    "status" => event["status"] = json!("failure"),
                    "outputs" => event["output_artifacts"] = json!(["artifact:forged"]),
                    "data-refs" => event["external_transfer"]["data_refs"] = json!([]),
                    "purpose" => event["external_transfer"]["purpose"] = json!("forged"),
                    _ => unreachable!(),
                }
                original_event_id.as_str()
            };
            let event_json = canonical_json(&event).unwrap();
            let event_hash = provenance_hash(
                "T-artifact",
                u64::try_from(sequence).unwrap(),
                previous_hash.as_deref(),
                &event,
            )
            .unwrap();
            let mut receipt: serde_json::Value = serde_json::from_str(&original_receipt).unwrap();
            receipt["provenance_event_id"] = json!(stored_event_id);
            receipt["provenance_event_hash"] = json!(event_hash);
            manager
                .connection
                .execute(
                    "UPDATE provenance_events
                     SET event_id=?1,event_json=?2,event_hash=?3
                     WHERE task_id='T-artifact' AND sequence=?4",
                    params![stored_event_id, event_json, event_hash, sequence],
                )
                .unwrap();
            manager
                .connection
                .execute(
                    "UPDATE operations SET external_receipt=?2 WHERE operation_id=?1",
                    params![operation_id, canonical_json(&receipt).unwrap()],
                )
                .unwrap();
            let replay = manager.issue_owned_artifact_export_destination(
                &scope,
                operation_id,
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(Vec::new()),
            );
            assert!(
                matches!(
                    replay,
                    Err(TaskManagerError::InvalidRecord(
                        "stored Artifact export receipt is invalid"
                    ))
                ),
                "{scenario}: {:?}",
                replay.as_ref().err()
            );
            let original_event: serde_json::Value =
                serde_json::from_str(&original_event_json).unwrap();
            let original_hash = provenance_hash(
                "T-artifact",
                u64::try_from(sequence).unwrap(),
                previous_hash.as_deref(),
                &original_event,
            )
            .unwrap();
            manager
                .connection
                .execute(
                    "UPDATE provenance_events SET event_id=?1,event_json=?2,event_hash=?3
                     WHERE task_id='T-artifact' AND sequence=?4",
                    params![
                        original_event_id,
                        original_event_json,
                        original_hash,
                        sequence
                    ],
                )
                .unwrap();
            manager
                .connection
                .execute(
                    "UPDATE operations SET external_receipt=?2 WHERE operation_id=?1",
                    params![operation_id, original_receipt],
                )
                .unwrap();
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "covers initial one-shot admission, in-process replay, and restart replay in one protocol regression"
    )]
    fn bound_export_exact_replay_reconstructs_after_one_shot_grant_consumption() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let mut manager = manager(&temp);
        let artifact = manager
            .import_artifact(
                &import_request(),
                &mut Cursor::new(b"one shot export replay".as_slice()),
            )
            .unwrap();
        let (binding_id, _) = install_one_shot_binding(
            &manager,
            "export-consumed-replay",
            std::slice::from_ref(&artifact.artifact_id),
            &[
                ("artifact.read", "artifact", &artifact.artifact_id),
                ("data.egress", "destination", "user-selected-file"),
            ],
        );
        let session = manager
            .issue_provider_artifact_session("T-artifact", &binding_id)
            .unwrap();
        let scope = manager
            .scope_artifact_reads(&session, std::slice::from_ref(&artifact.artifact_id))
            .unwrap();
        let mut first = manager
            .issue_legacy_fixture_artifact_export_destination(
                &session,
                &scope,
                "export-consumed-replay",
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(Vec::new()),
            )
            .unwrap();
        assert_eq!(
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut first)
                .unwrap(),
            22
        );
        let class_only_opens = Arc::new(AtomicUsize::new(0));
        assert!(
            manager
                .issue_bound_artifact_export_destination(
                    &session,
                    &scope,
                    "export-consumed-replay",
                    &artifact.artifact_id,
                    "user-selected-file",
                    1_024,
                    {
                        let opened = Arc::clone(&class_only_opens);
                        move || {
                            opened.fetch_add(1, Ordering::SeqCst);
                            Ok(Vec::<u8>::new())
                        }
                    },
                )
                .is_err(),
            "historical class-only operation cannot issue a fresh writer"
        );
        assert_eq!(class_only_opens.load(Ordering::SeqCst), 0);
        manager
            .register_trusted_export_service(
                "service://fixture/legacy",
                "user-selected-file",
                "adapter:memory",
            )
            .unwrap();
        assert!(
            manager
                .issue_exact_bound_artifact_export_destination(
                    &session,
                    &scope,
                    "export-consumed-replay",
                    &artifact.artifact_id,
                    "service://fixture/legacy",
                    "adapter:memory",
                    {
                        let opened = Arc::clone(&class_only_opens);
                        move || {
                            opened.fetch_add(1, Ordering::SeqCst);
                            Ok(Vec::<u8>::new())
                        }
                    },
                )
                .is_err(),
            "a historical class-only intent cannot acquire an exact pin after the fact"
        );
        assert_eq!(class_only_opens.load(Ordering::SeqCst), 0);
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state || ':' || uses_consumed FROM authority_grants
                     WHERE grant_id='grant-export-consumed-replay-1'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "CONSUMED:1"
        );

        manager
            .connection
            .execute(
                "UPDATE tasks SET state='RECOVERING' WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        assert_eq!(
            manager
                .replay_bound_artifact_export(&session, "export-consumed-replay")
                .unwrap(),
            22
        );
        manager
            .connection
            .execute(
                "UPDATE tasks SET state='RUNNING' WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        assert_eq!(
            manager
                .replay_bound_artifact_export(&session, "export-consumed-replay")
                .unwrap(),
            22
        );

        let opened = Arc::new(AtomicUsize::new(0));
        let observed = Arc::clone(&opened);
        let mut replay = manager
            .issue_legacy_fixture_artifact_export_destination(
                &session,
                &scope,
                "export-consumed-replay",
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                move || {
                    observed.fetch_add(1, Ordering::SeqCst);
                    Ok(Vec::new())
                },
            )
            .unwrap();
        assert_eq!(
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut replay)
                .unwrap(),
            22
        );
        assert_eq!(opened.load(Ordering::SeqCst), 0);

        // The binding fixture installs execution state directly. Restore the provenance-backed
        // Task view before reopening, then re-establish the fixture's execution view afterward.
        manager
            .connection
            .execute(
                "UPDATE tasks
                 SET state='CREATED',active_program_revision=NULL,active_step_ids_json='[]'
                 WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        drop(replay);
        drop(first);
        drop(scope);
        drop(session);
        drop(manager);
        let reopened = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        reopened
            .connection
            .execute(
                "UPDATE tasks
                 SET state='RUNNING',active_program_revision=1,
                     active_step_ids_json='[\"compose_report\"]'
                 WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        let session = reopened
            .issue_provider_artifact_session("T-artifact", &binding_id)
            .unwrap();
        assert!(matches!(
            reopened.scope_artifact_reads(&session, std::slice::from_ref(&artifact.artifact_id)),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        assert_eq!(
            reopened
                .replay_bound_artifact_export(&session, "export-consumed-replay")
                .unwrap(),
            22
        );
    }

