    #[test]
    fn owner_can_read_and_export_retained_artifacts_after_terminal_states() {
        for state in ["COMPLETED", "FAILED", "CANCELLED", "ROLLED_BACK"] {
            let temp = TempDir::new().unwrap();
            let mut manager = manager(&temp);
            let bytes = format!("retained after {state}").into_bytes();
            let artifact = manager
                .import_artifact(&import_request(), &mut Cursor::new(bytes.as_slice()))
                .unwrap();
            manager
                .connection
                .execute(
                    "UPDATE tasks SET state=?1 WHERE task_id='T-artifact'",
                    [state],
                )
                .unwrap();

            let scope = manager
                .scope_owned_artifact_reads("T-artifact", &[artifact.artifact_id.clone()])
                .unwrap();
            let mut reader = manager
                .open_artifact_reader(&scope, &artifact.artifact_id)
                .unwrap();
            let mut read = Vec::new();
            reader.read_to_end(&mut read).unwrap();
            assert_eq!(read, bytes, "owner read failed in {state}");

            let captured = Arc::new(Mutex::new(Vec::new()));
            let mut exported = manager
                .issue_owned_artifact_export_destination(
                    &scope,
                    &format!("terminal-owner-export-{state}"),
                    &artifact.artifact_id,
                    "user-selected-file",
                    1_024,
                    deferred(CapturedExportWriter(Arc::clone(&captured))),
                )
                .unwrap();
            manager
                .export_artifact(&scope, &artifact.artifact_id, &mut exported)
                .unwrap();
            assert!(exported.writer.is_none(), "owner export failed in {state}");
            assert_eq!(
                *captured.lock().unwrap(),
                bytes,
                "owner export failed in {state}"
            );
            assert_eq!(
                manager
                    .connection
                    .query_row(
                        "SELECT COUNT(*) FROM provenance_events WHERE task_id='T-artifact' AND event_type='artifact.exported'",
                        [],
                        |row| row.get::<_, i64>(0),
                    )
                    .unwrap(),
                1
            );
            let (program_hash, node_id) = manager
                .connection
                .query_row(
                    "SELECT semantic_program_hash,node_id FROM operations WHERE operation_id=?1",
                    [format!("terminal-owner-export-{state}")],
                    |row| {
                        Ok((
                            row.get::<_, Option<String>>(0)?,
                            row.get::<_, Option<String>>(1)?,
                        ))
                    },
                )
                .unwrap();
            assert_eq!((program_hash, node_id), (None, None));

            assert!(matches!(
                manager.import_artifact(
                    &import_request(),
                    &mut Cursor::new(b"late import".as_slice())
                ),
                Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
            ));
            let mut late_allocation = allocation(&format!("alloc-after-{state}"));
            late_allocation.expires_at = "2026-09-20T00:00:00Z".to_owned();
            assert!(matches!(
                manager.allocate_artifact_output(&late_allocation),
                Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
            ));
        }
    }

    #[test]
    fn in_memory_store_cleanup_waits_for_issued_reader_release() {
        let mut manager = TaskManager::open_in_memory_with_clock(Box::new(FixedClock)).unwrap();
        manager
            .create_task(&CreateTask {
                task_id: "T-memory-artifact".to_owned(),
                principal: Actor {
                    kind: "user".to_owned(),
                    id: "user:test".to_owned(),
                },
                workspace_id: None,
                original_intent: "exercise ephemeral cleanup".to_owned(),
                normalized_intent: None,
                active_step_ids: Vec::new(),
            })
            .unwrap();
        let mut request = import_request();
        request.task_id = "T-memory-artifact".to_owned();
        let artifact = manager
            .import_artifact(&request, &mut Cursor::new(b"ephemeral".as_slice()))
            .unwrap();
        let scope = manager
            .scope_owned_artifact_reads(
                "T-memory-artifact",
                std::slice::from_ref(&artifact.artifact_id),
            )
            .unwrap();
        let reader = manager
            .open_artifact_reader(&scope, &artifact.artifact_id)
            .unwrap();
        let root = manager.artifact_store_root.clone();
        drop(scope);
        drop(manager);
        assert!(root.exists());
        drop(reader);
        assert!(!root.exists());
    }

    #[test]
    fn sequential_one_shot_reads_ignore_an_expired_consumed_sibling_grant() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let first = manager
            .import_artifact(&import_request(), &mut Cursor::new(b"first".as_slice()))
            .unwrap();
        let second = manager
            .import_artifact(&import_request(), &mut Cursor::new(b"second".as_slice()))
            .unwrap();
        let (binding_id, _) = install_one_shot_binding(
            &manager,
            "two-reads",
            &[first.artifact_id.clone(), second.artifact_id.clone()],
            &[
                ("artifact.read", "artifact", &first.artifact_id),
                ("artifact.read", "artifact", &second.artifact_id),
            ],
        );
        let scope = scope_bound_reads(
            &manager,
            "T-artifact",
            &binding_id,
            &[first.artifact_id.clone(), second.artifact_id.clone()],
        )
        .unwrap();
        let mut first_reader = manager
            .open_artifact_reader(&scope, &first.artifact_id)
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE authority_grants SET expires_at='2026-09-19T21:00:00Z' WHERE grant_id='grant-two-reads-0'",
                [],
            )
            .unwrap();
        let mut byte = [0_u8; 1];
        assert_eq!(
            first_reader.read(&mut byte).unwrap_err().kind(),
            std::io::ErrorKind::PermissionDenied
        );

        let mut second_reader = manager
            .open_artifact_reader(&scope, &second.artifact_id)
            .unwrap();
        let mut bytes = Vec::new();
        second_reader.read_to_end(&mut bytes).unwrap();
        assert_eq!(bytes, b"second");
        assert!(matches!(
            scope_bound_reads(
                &manager,
                "T-artifact",
                &binding_id,
                &[first.artifact_id.clone()]
            ),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        let states = manager
            .connection
            .prepare(
                "SELECT state FROM authority_grants WHERE grant_id LIKE 'grant-two-reads-%' ORDER BY grant_id",
            )
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(states, ["CONSUMED", "CONSUMED"]);
    }

    #[test]
    fn retained_reader_cannot_resurrect_at_exact_expiry_after_wall_rollback() {
        let temp = TempDir::new().unwrap();
        let wall = Arc::new(Mutex::new("2026-09-19T22:00:00Z".to_owned()));
        let mut manager = manager_with_mutable_clock(&temp, &wall);
        let artifact = manager
            .import_artifact(&import_request(), &mut Cursor::new(b"protected".as_slice()))
            .unwrap();
        let (binding_id, _) = install_one_shot_binding(
            &manager,
            "time-floor",
            std::slice::from_ref(&artifact.artifact_id),
            &[("artifact.read", "artifact", &artifact.artifact_id)],
        );
        let scope = scope_bound_reads(
            &manager,
            "T-artifact",
            &binding_id,
            std::slice::from_ref(&artifact.artifact_id),
        )
        .unwrap();
        let mut reader = manager
            .open_artifact_reader(&scope, &artifact.artifact_id)
            .unwrap();
        let before: i64 = manager
            .connection
            .query_row(
                "SELECT uses_consumed FROM authority_grants WHERE grant_id='grant-time-floor-0'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        *wall.lock().unwrap() = "2026-09-20T00:00:00Z".to_owned();
        let mut byte = [0_u8; 1];
        assert_eq!(
            reader.read(&mut byte).unwrap_err().kind(),
            std::io::ErrorKind::PermissionDenied
        );
        *wall.lock().unwrap() = "2026-09-19T22:00:00Z".to_owned();
        assert_eq!(
            reader.read(&mut byte).unwrap_err().kind(),
            std::io::ErrorKind::PermissionDenied
        );
        assert!(matches!(
            manager.open_artifact_reader(&scope, &artifact.artifact_id),
            Err(TaskManagerError::InvalidRecord("TIME_UNCERTAIN"))
        ));
        let after: i64 = manager
            .connection
            .query_row(
                "SELECT uses_consumed FROM authority_grants WHERE grant_id='grant-time-floor-0'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(after, before);
        let (confidence, audit): (String, i64) = manager
            .connection
            .query_row(
                "SELECT confidence,(SELECT COUNT(*) FROM trusted_time_observations)
             FROM trusted_time_state WHERE singleton_id=1",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(confidence, "TIME_UNCERTAIN");
        assert!(audit >= 3);
    }

    #[test]
    fn running_transition_replay_cannot_erase_forward_time_and_resurrect_read_grant() {
        let temp = TempDir::new().unwrap();
        let wall = Arc::new(Mutex::new("2026-09-19T22:00:00Z".to_owned()));
        let mut manager = manager_with_mutable_clock(&temp, &wall);
        let artifact = manager
            .import_artifact(&import_request(), &mut Cursor::new(b"replay".as_slice()))
            .unwrap();
        let (binding_id, _) = install_one_shot_binding(
            &manager,
            "time-replay",
            std::slice::from_ref(&artifact.artifact_id),
            &[("artifact.read", "artifact", &artifact.artifact_id)],
        );
        let scope = scope_bound_reads(
            &manager,
            "T-artifact",
            &binding_id,
            std::slice::from_ref(&artifact.artifact_id),
        )
        .unwrap();
        let request = crate::TransitionRequest {
            schema_version: crate::SCHEMA_VERSION.to_owned(),
            transition_id: "tr-time-replay".to_owned(),
            task_id: "T-artifact".to_owned(),
            expected_revision: 1,
            expected_state: crate::TaskState::Created,
            to_state: crate::TaskState::Running,
            requested_by: Actor {
                kind: "system-service".to_owned(),
                id: "service:task-manager".to_owned(),
            },
            reason: crate::TransitionReason {
                code: "STATE_CHANGE_REQUESTED".to_owned(),
                message: None,
                related_ids: Vec::new(),
            },
            mutation: crate::TaskMutation::default(),
        };
        let original = manager.transition(&request).unwrap();
        assert!(!original.applied);
        *wall.lock().unwrap() = "2026-09-20T00:00:00Z".to_owned();
        assert_eq!(manager.transition(&request).unwrap(), original);
        let before_conflict: i64 = manager
            .connection
            .query_row(
                "SELECT high_water_unix_nanos FROM trusted_time_state WHERE singleton_id=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        *wall.lock().unwrap() = "2026-09-20T01:00:00Z".to_owned();
        let mut conflicting = request.clone();
        conflicting.reason.message = Some("changed request".to_owned());
        assert_eq!(
            manager.transition(&conflicting).unwrap().reason_code,
            "TASK_TRANSITION_ID_REUSE_CONFLICT"
        );
        let after_conflict: i64 = manager
            .connection
            .query_row(
                "SELECT high_water_unix_nanos FROM trusted_time_state WHERE singleton_id=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(after_conflict > before_conflict);
        *wall.lock().unwrap() = "2026-09-19T22:00:00Z".to_owned();
        assert!(matches!(
            manager.open_artifact_reader(&scope, &artifact.artifact_id),
            Err(TaskManagerError::InvalidRecord("TIME_UNCERTAIN"))
        ));
        let uses: i64 = manager
            .connection
            .query_row(
                "SELECT uses_consumed FROM authority_grants WHERE grant_id='grant-time-replay-0'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(uses, 0);
    }

