    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "authenticates the complete committed publication receipt and durable blob replay path"
    )]
    fn committed_replay_authenticates_receipt_rows_and_blob_bytes() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        manager
            .allocate_artifact_output(&allocation("alloc-replay"))
            .unwrap();
        write_output(&mut manager, "alloc-replay", b"replay");
        let request = publication("pub-replay", "alloc-replay");
        let original = manager.publish_artifact_output(&request).unwrap();
        assert!(original.published);
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=json_set(result_json,'$.blob_reused',NULL) WHERE publication_id='pub-replay'",
                [],
            )
            .unwrap();
        let missing_reuse = manager.publish_artifact_output(&request).unwrap();
        assert!(!missing_reuse.published);
        assert_eq!(missing_reuse.reason_code, "ARTIFACT_INTEGRITY_FAILED");
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=?2 WHERE publication_id=?1",
                params![
                    request.publication_id,
                    serde_json::to_string(&original).unwrap()
                ],
            )
            .unwrap();
        let mut forged_reuse = original.clone();
        forged_reuse.blob_reused = original.blob_reused.map(|value| !value);
        let mut forged_message = original.clone();
        forged_message.message = Some("forged success detail".to_owned());
        for forged in [forged_reuse, forged_message] {
            manager
                .connection
                .execute(
                    "UPDATE artifact_publications SET result_json=?2 WHERE publication_id=?1",
                    params![
                        request.publication_id,
                        serde_json::to_string(&forged).unwrap()
                    ],
                )
                .unwrap();
            let rejected = manager.publish_artifact_output(&request).unwrap();
            assert!(!rejected.published);
            assert_eq!(rejected.reason_code, "ARTIFACT_INTEGRITY_FAILED");
        }
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=?2 WHERE publication_id=?1",
                params![
                    request.publication_id,
                    serde_json::to_string(&original).unwrap()
                ],
            )
            .unwrap();
        PUBLICATION_REPLAY_HASH_TEST_HOOK.with(|hook| {
            *hook.borrow_mut() = Some(Box::new(|| {
                Err(TaskManagerError::Io(std::io::Error::new(
                    std::io::ErrorKind::Interrupted,
                    "injected transient replay read failure",
                )))
            }));
        });
        assert!(matches!(
            manager.publish_artifact_output(&request),
            Err(TaskManagerError::Io(error)) if error.kind() == std::io::ErrorKind::Interrupted
        ));
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT a.integrity_state || ':' || b.durability_state
                     FROM artifacts a JOIN artifact_blobs b ON b.content_hash=a.content_hash
                     WHERE a.artifact_id=?1",
                    [original.artifact_id.as_deref().unwrap()],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "verified:DURABLE"
        );
        assert_eq!(manager.publish_artifact_output(&request).unwrap(), original);
        let artifact_id = original.artifact_id.as_deref().unwrap();
        let scope = manager
            .scope_owned_artifact_reads("T-artifact", &[artifact_id.to_owned()])
            .unwrap();
        let mut reader = manager.open_artifact_reader(&scope, artifact_id).unwrap();
        let mut bytes = Vec::new();
        reader.read_to_end(&mut bytes).unwrap();
        assert_eq!(bytes, b"replay");
        assert_eq!(manager.publish_artifact_output(&request).unwrap(), original);

        let immutable_metadata = manager
            .connection
            .query_row(
                "SELECT expires_at,integrity_verified_at,integrity_verifier,created_at
                 FROM artifacts WHERE artifact_id=?1",
                [artifact_id],
                |row| {
                    Ok((
                        row.get::<_, Option<String>>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, String>(3)?,
                    ))
                },
            )
            .unwrap();
        for (column, forged, original_value) in [
            (
                "expires_at",
                "2027-01-01T00:00:00Z",
                immutable_metadata.0.as_deref(),
            ),
            (
                "integrity_verified_at",
                "2027-01-02T00:00:00Z",
                immutable_metadata.1.as_deref(),
            ),
            (
                "integrity_verifier",
                "forged:verifier",
                immutable_metadata.2.as_deref(),
            ),
            (
                "created_at",
                "2027-01-03T00:00:00Z",
                Some(immutable_metadata.3.as_str()),
            ),
        ] {
            manager
                .connection
                .execute(
                    &format!("UPDATE artifacts SET {column}=?1 WHERE artifact_id=?2"),
                    params![forged, artifact_id],
                )
                .unwrap();
            let rejected = manager.publish_artifact_output(&request).unwrap();
            assert!(!rejected.published, "replay accepted forged {column}");
            assert_eq!(rejected.reason_code, "ARTIFACT_INTEGRITY_FAILED");
            manager
                .connection
                .execute(
                    &format!("UPDATE artifacts SET {column}=?1 WHERE artifact_id=?2"),
                    params![original_value, artifact_id],
                )
                .unwrap();
            assert_eq!(manager.publish_artifact_output(&request).unwrap(), original);
        }
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=json_set(result_json,'$.size_bytes',999) WHERE publication_id='pub-replay'",
                [],
            )
            .unwrap();
        let replay = manager.publish_artifact_output(&request).unwrap();
        assert!(!replay.published);
        assert_eq!(replay.reason_code, "ARTIFACT_INTEGRITY_FAILED");
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=?2 WHERE publication_id=?1",
                params![
                    request.publication_id,
                    serde_json::to_string(&original).unwrap()
                ],
            )
            .unwrap();
        let storage_ref = manager
            .connection
            .query_row(
                "SELECT storage_ref FROM artifact_blobs WHERE content_hash=?1",
                [original.content_hash.as_deref().unwrap()],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        manager
            .artifact_store_dir
            .remove_file(&storage_ref)
            .unwrap();
        authenticate_running_fixture_history(&mut manager, "T-artifact");
        CONTENT_HASH_HANDOFF_TEST_HOOK.with(|hook| {
            *hook.borrow_mut() = Some(Box::new(|| {
                Err(TaskManagerError::Io(std::io::Error::other(
                    "injected committed publication damage handoff failure",
                )))
            }));
        });
        assert!(matches!(
            manager.publish_artifact_output(&request),
            Err(TaskManagerError::Io(_))
        ));
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state FROM tasks WHERE task_id='T-artifact'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "RUNNING"
        );
        manager
            .connection
            .execute(
                "UPDATE artifact_publications
                 SET result_json=json_set(result_json,'$.message','forged sticky damage')
                 WHERE publication_id=?1",
                [&request.publication_id],
            )
            .unwrap();
        let forged_damage = manager.publish_artifact_output(&request).unwrap();
        assert_eq!(forged_damage.reason_code, "ARTIFACT_INTEGRITY_FAILED");
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state FROM tasks WHERE task_id='T-artifact'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "RUNNING",
            "a forged committed receipt must not trigger a recovery handoff"
        );
        manager
            .connection
            .execute(
                "UPDATE artifact_publications SET result_json=?2 WHERE publication_id=?1",
                params![request.publication_id, canonical_json(&original).unwrap()],
            )
            .unwrap();
        let missing = manager.publish_artifact_output(&request).unwrap();
        assert!(!missing.published);
        assert_eq!(missing.reason_code, "ARTIFACT_INTEGRITY_FAILED");
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state FROM tasks WHERE task_id='T-artifact'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "RECOVERING"
        );
    }

    #[test]
    fn startup_does_not_launder_forged_publication_verification_time() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let mut manager = manager(&temp);
        manager
            .allocate_artifact_output(&allocation("alloc-legacy-verification"))
            .unwrap();
        write_output(
            &mut manager,
            "alloc-legacy-verification",
            b"legacy verified",
        );
        let request = publication("pub-legacy-verification", "alloc-legacy-verification");
        let original = manager.publish_artifact_output(&request).unwrap();
        let artifact_id = original.artifact_id.as_deref().unwrap();
        manager
            .connection
            .execute(
                "UPDATE artifacts SET integrity_verified_at='2026-09-19T23:00:00Z'
                 WHERE artifact_id=?1",
                [artifact_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "UPDATE artifact_blobs SET verified_at='2026-09-19T23:00:00Z'
                 WHERE content_hash=?1",
                [original.content_hash.as_deref().unwrap()],
            )
            .unwrap();
        drop(manager);

        let mut reopened = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        assert_eq!(
            reopened
                .get_artifact(artifact_id)
                .unwrap()
                .unwrap()
                .integrity
                .unwrap()
                .verified_at
                .as_deref(),
            Some("2026-09-19T23:00:00Z")
        );
        let replay = reopened.publish_artifact_output(&request);
        let replay = replay.unwrap();
        assert!(!replay.published);
        assert_eq!(replay.reason_code, "ARTIFACT_INTEGRITY_FAILED");
    }

    #[test]
    fn hardlink_database_alias_reuses_bound_artifact_root() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let alias = temp.path().join("database-alias.sqlite");
        let manager = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        let root = manager.artifact_store_root.clone();
        drop(manager);
        std::fs::hard_link(&database, &alias).unwrap();
        let reopened = TaskManager::open_with_clock(&alias, Box::new(FixedClock)).unwrap();
        assert_eq!(reopened.artifact_store_root, root);
        let bound_root = reopened
            .connection
            .query_row(
                "SELECT canonical_root FROM artifact_store_binding WHERE singleton_id=1",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        assert_eq!(PathBuf::from(bound_root), root);
        let attacker_root = TempDir::new().unwrap();
        reopened
            .connection
            .execute(
                "UPDATE artifact_store_binding SET canonical_root=?1 WHERE singleton_id=1",
                [attacker_root.path().to_string_lossy().as_ref()],
            )
            .unwrap();
        drop(reopened);
        let reopened = TaskManager::open_with_clock(&alias, Box::new(FixedClock));
        assert!(matches!(
            reopened,
            Err(TaskManagerError::InvalidRecord(message))
                if message == "Artifact store root identity does not match its database binding"
                    || message == "Artifact store ownership or ACL is untrusted"
                    || message == "opened Artifact store ownership or permissions are untrusted"
        ));
    }

    #[test]
    fn artifact_handle_accepts_the_published_optional_wire_shape() {
        let minimal = json!({
            "artifact_id":"artifact:minimal",
            "uri":"artifact://artifact:minimal",
            "media_type":"application/octet-stream",
            "origin":{"kind":"user"},
            "sensitivity":"private"
        });
        let handle: ArtifactHandle = serde_json::from_value(minimal).unwrap();
        assert_eq!(handle.size_bytes, None);
        assert_eq!(handle.content_hash, None);
        assert_eq!(handle.retention, None);
        assert_eq!(handle.integrity, None);
        assert_eq!(handle.created_at, None);

        let nullable: ArtifactHandle = serde_json::from_value(json!({
            "artifact_id":"artifact:nullable",
            "uri":"artifact://artifact:nullable",
            "semantic_type":null,
            "media_type":"application/octet-stream",
            "format":null,
            "size_bytes":null,
            "content_hash":null,
            "origin":{"kind":"user"},
            "sensitivity":"private",
            "created_at":null
        }))
        .unwrap();
        assert_eq!(nullable.size_bytes, None);
        assert_eq!(nullable.content_hash, None);
    }

    #[test]
    fn output_allocation_wire_defaults_omitted_allowed_media_types() {
        let mut value = serde_json::to_value(ArtifactOutputAllocation {
            schema_version: SCHEMA_VERSION.to_owned(),
            allocation_id: "allocation:wire-default".to_owned(),
            task_id: "T-artifact".to_owned(),
            semantic_program_hash: allocation("unused").semantic_program_hash,
            node_id: "compose_report".to_owned(),
            binding_id: None,
            attempt_id: None,
            output_port: Some("report".to_owned()),
            expected_semantic_type: Some("artifact.report@1".to_owned()),
            allowed_media_types: Vec::new(),
            max_size_bytes: None,
            sensitivity: Sensitivity::Private,
            retention: RetentionClass::Task,
            state: ArtifactAllocationState::Allocated,
            publication_id: None,
            published_artifact_id: None,
            created_at: "2026-09-19T22:00:00Z".to_owned(),
            expires_at: "2026-09-19T23:00:00Z".to_owned(),
            updated_at: None,
        })
        .unwrap();
        value.as_object_mut().unwrap().remove("allowed_media_types");
        let decoded: ArtifactOutputAllocation = serde_json::from_value(value).unwrap();
        assert!(decoded.allowed_media_types.is_empty());

        let mut empty_identifiers = serde_json::to_value(&decoded).unwrap();
        for field in [
            "binding_id",
            "attempt_id",
            "output_port",
            "publication_id",
            "published_artifact_id",
        ] {
            empty_identifiers[field] = json!("");
        }
        assert_json_matches_schema("artifact-output-allocation.schema.json", &empty_identifiers);
        let decoded_empty: ArtifactOutputAllocation =
            serde_json::from_value(empty_identifiers).unwrap();
        assert_eq!(decoded_empty.binding_id.as_deref(), Some(""));
        assert_eq!(decoded_empty.attempt_id.as_deref(), Some(""));
        assert_eq!(decoded_empty.output_port.as_deref(), Some(""));
        assert_eq!(decoded_empty.publication_id.as_deref(), Some(""));
        assert_eq!(decoded_empty.published_artifact_id.as_deref(), Some(""));

        let canonical = serde_json::to_value(&decoded).unwrap();
        for (name, pointer, replacement) in [
            ("schema", "/schema_version", json!("9.9")),
            ("node", "/node_id", json!("")),
            (
                "duplicate-media",
                "/allowed_media_types",
                json!(["application/json", "application/json"]),
            ),
            ("created-at", "/created_at", json!("not-rfc3339")),
            ("expires-at", "/expires_at", json!("not-rfc3339")),
        ] {
            let mut invalid = canonical.clone();
            *invalid.pointer_mut(pointer).unwrap() = replacement;
            assert!(
                serde_json::from_value::<ArtifactOutputAllocation>(invalid).is_err(),
                "{name}"
            );
        }
        let mut unknown = canonical;
        unknown
            .as_object_mut()
            .unwrap()
            .insert("unexpected".to_owned(), json!(true));
        assert!(serde_json::from_value::<ArtifactOutputAllocation>(unknown).is_err());
    }

    #[test]
    fn bound_output_policy_is_conservatively_derived_from_durable_attempt_inputs() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let mut input_request = import_request();
        input_request.sensitivity = Sensitivity::Secret;
        input_request.retention = RetentionClass::Persistent;
        let input = manager
            .import_artifact(
                &input_request,
                &mut Cursor::new(b"classified input".as_slice()),
            )
            .unwrap();
        let allocation_id = "allocation:derived-classification";
        let (binding_id, attempt_id) = install_one_shot_binding(
            &manager,
            "derived-classification",
            std::slice::from_ref(&input.artifact_id),
            &[("artifact.write", "output-allocation", allocation_id)],
        );
        let session = session_for_binding(&manager, "T-artifact", &binding_id);
        let mut request = allocation(allocation_id);
        request.binding_id = Some(binding_id);
        request.attempt_id = Some(attempt_id);
        assert!(matches!(
            manager.allocate_bound_artifact_output(&session, &request),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
        assert!(
            manager
                .get_artifact_output_allocation(allocation_id)
                .unwrap()
                .is_none()
        );

        request.sensitivity = Sensitivity::Secret;
        request.retention = RetentionClass::Persistent;
        let created = manager
            .allocate_bound_artifact_output(&session, &request)
            .unwrap();
        assert_eq!(created.sensitivity, Sensitivity::Secret);
        assert_eq!(created.retention, RetentionClass::Persistent);
    }

    #[test]
    fn keyed_import_replays_after_lost_commit_response_without_reading_source() {
        struct PanicReader;
        impl Read for PanicReader {
            fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
                panic!("a committed keyed import replay must not read the source")
            }
        }

        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let mut request = import_request();
        request.import_id = Some("import:stable-response-loss".to_owned());
        IMPORT_COMMIT_RESULT_TEST_HOOK.with(|hook| {
            *hook.borrow_mut() = Some(Box::new(|| {
                Err(TaskManagerError::Io(std::io::Error::other(
                    "injected late import commit result",
                )))
            }));
        });
        assert!(
            manager
                .import_artifact(&request, &mut Cursor::new(b"stable import".as_slice()))
                .is_err()
        );
        let replayed = manager.import_artifact(&request, &mut PanicReader).unwrap();
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM artifacts WHERE artifact_id=?1",
                    [&replayed.artifact_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM provenance_events WHERE task_id='T-artifact'
                     AND event_type='artifact.imported'
                     AND json_extract(event_json,'$.details.import_id')=?1",
                    [request.import_id.as_deref().unwrap()],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );

        manager
            .connection
            .execute(
                "UPDATE tasks SET state='RECOVERING' WHERE task_id='T-artifact'",
                [],
            )
            .unwrap();
        assert_eq!(
            manager.import_artifact(&request, &mut PanicReader).unwrap(),
            replayed
        );
        let mut new_request = request.clone();
        new_request.import_id = Some("import:new-during-recovery".to_owned());
        assert!(matches!(
            manager.import_artifact(&new_request, &mut PanicReader),
            Err(TaskManagerError::InvalidRecord("ARTIFACT_AUTHORITY_DENIED"))
        ));
    }

    #[test]
    fn keyed_import_replay_uses_causal_receipt_when_blob_imports_share_a_timestamp() {
        struct PanicReader;
        impl Read for PanicReader {
            fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
                panic!("a keyed import replay must not read its source")
            }
        }

        let temp = TempDir::new().unwrap();
        let now = Arc::new(Mutex::new("2026-09-19T22:00:00Z".to_owned()));
        let mut manager = manager_with_mutable_clock(&temp, &now);
        let mut first_request = import_request();
        first_request.import_id = Some("import:same-clock-first".to_owned());
        let mut second_request = first_request.clone();
        second_request.import_id = Some("import:same-clock-second".to_owned());
        let bytes = b"same blob and same timestamp";
        let first = manager
            .import_artifact(&first_request, &mut Cursor::new(bytes.as_slice()))
            .unwrap();
        let second = manager
            .import_artifact(&second_request, &mut Cursor::new(bytes.as_slice()))
            .unwrap();

        for (request, expected_reused) in [(&first_request, false), (&second_request, true)] {
            let operation_id =
                keyed_import_operation_id(&request.task_id, request.import_id.as_deref().unwrap());
            let receipt: serde_json::Value = serde_json::from_str(
                &manager
                    .connection
                    .query_row(
                        "SELECT external_receipt FROM operations WHERE operation_id=?1",
                        [&operation_id],
                        |row| row.get::<_, String>(0),
                    )
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(
                receipt
                    .get("blob_reused")
                    .and_then(serde_json::Value::as_bool),
                Some(expected_reused)
            );
            manager.import_artifact(request, &mut PanicReader).unwrap();
        }
        assert_ne!(first.artifact_id, second.artifact_id);

        let first_operation = keyed_import_operation_id(
            &first_request.task_id,
            first_request.import_id.as_deref().unwrap(),
        );
        manager
            .connection
            .execute(
                "UPDATE operations
                 SET external_receipt=json_set(external_receipt,'$.blob_reused',1)
                 WHERE operation_id=?1",
                [&first_operation],
            )
            .unwrap();
        assert!(matches!(
            manager.import_artifact(&first_request, &mut PanicReader),
            Err(TaskManagerError::InvalidRecord(
                "stored Artifact import receipt is invalid"
            ))
        ));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one upgrade fixture covers legacy atomic backfill plus modern receipt tamper and deletion rejection"
    )]
    fn legacy_keyed_import_is_atomically_backfilled_but_modern_receipt_is_mandatory() {
        struct PanicReader;
        impl Read for PanicReader {
            fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
                panic!("an authenticated keyed import replay must not read its source")
            }
        }

        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let mut manager = manager(&temp);
        let mut request = import_request();
        request.import_id = Some("import:pre-causal-receipt-layout".to_owned());
        let artifact = manager
            .import_artifact(&request, &mut Cursor::new(b"legacy keyed bytes".as_slice()))
            .unwrap();
        let operation_id =
            keyed_import_operation_id(&request.task_id, request.import_id.as_deref().unwrap());
        manager
            .connection
            .execute(
                "DELETE FROM operations WHERE operation_id=?1",
                [&operation_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "DELETE FROM schema_migrations
                 WHERE migration_id='0010_keyed_import_causal_receipts'",
                [],
            )
            .unwrap();
        drop(manager);

        let mut reopened = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM operations WHERE operation_id=?1
                       AND effect_class='ARTIFACT_IMPORT' AND state='SUCCEEDED'
                       AND outcome_certainty='COMPLETED'",
                    [&operation_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
        assert_eq!(
            reopened
                .import_artifact(&request, &mut PanicReader)
                .unwrap()
                .artifact_id,
            artifact.artifact_id
        );

        let original_receipt = reopened
            .connection
            .query_row(
                "SELECT external_receipt FROM operations WHERE operation_id=?1",
                [&operation_id],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        reopened
            .connection
            .execute(
                "UPDATE operations
                 SET external_receipt=json_set(external_receipt,'$.blob_reused',
                                               NOT json_extract(external_receipt,'$.blob_reused'))
                 WHERE operation_id=?1",
                [&operation_id],
            )
            .unwrap();
        assert!(matches!(
            reopened.import_artifact(&request, &mut PanicReader),
            Err(TaskManagerError::InvalidRecord(
                "stored Artifact import receipt is invalid"
            ))
        ));
        reopened
            .connection
            .execute(
                "UPDATE operations SET external_receipt=?2 WHERE operation_id=?1",
                params![operation_id, original_receipt],
            )
            .unwrap();
        reopened
            .connection
            .execute(
                "DELETE FROM operations WHERE operation_id=?1",
                [&operation_id],
            )
            .unwrap();
        assert!(matches!(
            reopened.import_artifact(&request, &mut PanicReader),
            Err(TaskManagerError::InvalidRecord(
                "stored Artifact import receipt is invalid"
            ))
        ));
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM schema_migrations
                     WHERE migration_id='0010_keyed_import_causal_receipts'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "covers two legacy imports sharing one damaged blob and their complete recovery evidence"
    )]
    fn damaged_legacy_keyed_import_is_quarantined_into_recovery_instead_of_fabricated() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let mut manager = manager(&temp);
        let mut request = import_request();
        request.import_id = Some("import:damaged-legacy".to_owned());
        let artifact = manager
            .import_artifact(
                &request,
                &mut Cursor::new(b"legacy bytes that disappeared".as_slice()),
            )
            .unwrap();
        manager
            .create_task(&CreateTask {
                task_id: "T-artifact-nonlegacy-owner".to_owned(),
                principal: Actor {
                    kind: "user".to_owned(),
                    id: "user:test".to_owned(),
                },
                workspace_id: None,
                original_intent: "share a damaged legacy blob".to_owned(),
                normalized_intent: None,
                active_step_ids: Vec::new(),
            })
            .unwrap();
        let mut nonlegacy_request = request.clone();
        nonlegacy_request.task_id = "T-artifact-nonlegacy-owner".to_owned();
        nonlegacy_request.import_id = None;
        let nonlegacy_artifact = manager
            .import_artifact(
                &nonlegacy_request,
                &mut Cursor::new(b"legacy bytes that disappeared".as_slice()),
            )
            .unwrap();
        assert_eq!(artifact.content_hash, nonlegacy_artifact.content_hash);
        let mut second_request = request.clone();
        second_request.import_id = Some("import:damaged-legacy-shared".to_owned());
        let second_artifact = manager
            .import_artifact(
                &second_request,
                &mut Cursor::new(b"legacy bytes that disappeared".as_slice()),
            )
            .unwrap();
        assert_eq!(artifact.content_hash, second_artifact.content_hash);
        let operation_id =
            keyed_import_operation_id(&request.task_id, request.import_id.as_deref().unwrap());
        let second_operation_id = keyed_import_operation_id(
            &second_request.task_id,
            second_request.import_id.as_deref().unwrap(),
        );
        let storage_ref = manager
            .connection
            .query_row(
                "SELECT storage_ref FROM artifact_blobs WHERE content_hash=?1",
                [artifact.content_hash.as_ref().unwrap().tagged()],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        manager
            .connection
            .execute(
                "DELETE FROM operations WHERE operation_id IN (?1,?2)",
                params![operation_id, second_operation_id],
            )
            .unwrap();
        manager
            .connection
            .execute(
                "DELETE FROM schema_migrations
                 WHERE migration_id='0010_keyed_import_causal_receipts'",
                [],
            )
            .unwrap();
        manager
            .artifact_store_dir
            .remove_file(safe_internal_ref(&storage_ref).unwrap())
            .unwrap();
        drop(manager);

        let reopened = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT a.integrity_state || ':' || b.durability_state
                     FROM artifacts a JOIN artifact_blobs b ON b.content_hash=a.content_hash
                     WHERE a.artifact_id=?1",
                    [&artifact.artifact_id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "failed:MISSING"
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT a.integrity_state || ':' || b.durability_state
                     FROM artifacts a JOIN artifact_blobs b ON b.content_hash=a.content_hash
                     WHERE a.artifact_id=?1",
                    [&second_artifact.artifact_id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "failed:MISSING"
        );
        let damage_operation_id =
            legacy_import_damage_operation_id(&request.task_id, &artifact.artifact_id);
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT state || ':' || outcome_certainty FROM operations
                     WHERE operation_id=?1",
                    [&damage_operation_id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "UNKNOWN:OUTCOME_UNKNOWN"
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM recovery_unknown_operations
                     WHERE operation_id=?1",
                    [format!("operation:{damage_operation_id}")],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
        let second_damage_operation_id = legacy_import_damage_operation_id(
            &second_request.task_id,
            &second_artifact.artifact_id,
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM recovery_unknown_operations
                     WHERE operation_id IN (?1,?2)",
                    params![
                        format!("operation:{damage_operation_id}"),
                        format!("operation:{second_damage_operation_id}")
                    ],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            2
        );
        let nonlegacy_damage_operation_id = legacy_import_damage_operation_id(
            &nonlegacy_request.task_id,
            &nonlegacy_artifact.artifact_id,
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM recovery_unknown_operations WHERE operation_id=?1",
                    [format!("operation:{nonlegacy_damage_operation_id}")],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1,
            "every task owning the damaged blob needs recovery evidence"
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM operations WHERE operation_id=?1",
                    [&operation_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0,
            "migration must not fabricate a successful causal receipt"
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM operations WHERE operation_id=?1",
                    [&second_operation_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0,
            "migration must not fabricate the second successful causal receipt"
        );
    }

    #[test]
    fn damaged_legacy_import_marker_and_recovery_inventory_commit_atomically() {
        let temp = TempDir::new().unwrap();
        let database = temp.path().join("task-manager.sqlite");
        let (artifact_id, damage_operation_id) = {
            let mut manager = manager(&temp);
            let mut request = import_request();
            request.import_id = Some("import:atomic-damaged-legacy".to_owned());
            let artifact = manager
                .import_artifact(&request, &mut Cursor::new(b"legacy damage".as_slice()))
                .unwrap();
            let operation_id =
                keyed_import_operation_id(&request.task_id, request.import_id.as_deref().unwrap());
            let storage_ref = manager
                .connection
                .query_row(
                    "SELECT storage_ref FROM artifact_blobs WHERE content_hash=?1",
                    [artifact.content_hash.as_ref().unwrap().tagged()],
                    |row| row.get::<_, String>(0),
                )
                .unwrap();
            manager
                .connection
                .execute(
                    "DELETE FROM operations WHERE operation_id=?1",
                    [&operation_id],
                )
                .unwrap();
            manager
                .connection
                .execute_batch(
                    "DELETE FROM schema_migrations
                 WHERE migration_id='0010_keyed_import_causal_receipts';
                 CREATE TRIGGER reject_atomic_damage_inventory
                 BEFORE INSERT ON recovery_assessments
                 BEGIN SELECT RAISE(ABORT,'injected recovery inventory failure'); END;",
                )
                .unwrap();
            manager
                .artifact_store_dir
                .remove_file(safe_internal_ref(&storage_ref).unwrap())
                .unwrap();
            let damage_operation_id =
                legacy_import_damage_operation_id(&request.task_id, &artifact.artifact_id);
            (artifact.artifact_id, damage_operation_id)
        };

        assert!(TaskManager::open_with_clock(&database, Box::new(FixedClock)).is_err());
        let connection = Connection::open(&database).unwrap();
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM schema_migrations
                     WHERE migration_id='0010_keyed_import_causal_receipts'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM operations WHERE operation_id=?1",
                    [&damage_operation_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        connection
            .execute_batch("DROP TRIGGER reject_atomic_damage_inventory")
            .unwrap();
        drop(connection);

        let reopened = TaskManager::open_with_clock(&database, Box::new(FixedClock)).unwrap();
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT COUNT(*) FROM recovery_unknown_operations
                     WHERE operation_id=?1",
                    [format!("operation:{damage_operation_id}")],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
        assert_eq!(
            reopened
                .connection
                .query_row(
                    "SELECT integrity_state FROM artifacts WHERE artifact_id=?1",
                    [artifact_id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "failed"
        );
    }

    #[test]
    fn keyed_import_replays_after_later_read_and_export_integrity_verification() {
        struct PanicReader;
        impl Read for PanicReader {
            fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
                panic!("a keyed import replay must not read its source")
            }
        }

        let temp = TempDir::new().unwrap();
        let now = Arc::new(Mutex::new("2026-09-19T22:00:00Z".to_owned()));
        let mut manager = manager_with_mutable_clock(&temp, &now);
        let mut request = import_request();
        request.import_id = Some("import:later-integrity-verification".to_owned());
        let artifact = manager
            .import_artifact(&request, &mut Cursor::new(b"verified later".as_slice()))
            .unwrap();
        *now.lock().unwrap() = "2026-09-19T22:30:00Z".to_owned();
        let scope = manager
            .scope_owned_artifact_reads("T-artifact", &[artifact.artifact_id.clone()])
            .unwrap();
        let mut reader = manager
            .open_artifact_reader(&scope, &artifact.artifact_id)
            .unwrap();
        let mut bytes = Vec::new();
        reader.read_to_end(&mut bytes).unwrap();
        drop(reader);
        assert_eq!(bytes, b"verified later");
        let mut destination = manager
            .issue_owned_artifact_export_destination(
                &scope,
                "export-keyed-import-after-read",
                &artifact.artifact_id,
                "user-selected-file",
                1_024,
                deferred(Vec::new()),
            )
            .unwrap();
        manager
            .export_artifact(&scope, &artifact.artifact_id, &mut destination)
            .unwrap();

        let replayed = manager.import_artifact(&request, &mut PanicReader).unwrap();
        assert_eq!(replayed.artifact_id, artifact.artifact_id);
        assert_eq!(
            replayed.integrity.unwrap().verified_at.as_deref(),
            Some("2026-09-19T22:00:00Z")
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one table-driven test covers immutable metadata and the complete import provenance envelope"
    )]
    fn keyed_import_replay_authenticates_every_immutable_artifact_field() {
        struct PanicReader;
        impl Read for PanicReader {
            fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
                panic!("a keyed import replay must not read its source")
            }
        }

        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let mut request = import_request();
        request.import_id = Some("import:metadata-authentication".to_owned());
        request.semantic_type = Some("text.plain@1".to_owned());
        request.format = Some("txt".to_owned());
        request.labels = vec!["canonical".to_owned()];
        let artifact = manager
            .import_artifact(&request, &mut Cursor::new(b"immutable metadata".as_slice()))
            .unwrap();
        manager
            .connection
            .execute_batch(
                "DROP TRIGGER published_artifacts_no_content_update;
                 PRAGMA foreign_keys=OFF;",
            )
            .unwrap();

        let forged_hash = format!("sha256:{}", "a".repeat(64));
        let mutations = [
            "UPDATE artifacts SET uri='artifact://forged' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET semantic_type='text.forged@1' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET media_type='application/forged' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET format='forged' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET size_bytes=size_bytes+1 WHERE artifact_id=?1".to_owned(),
            format!("UPDATE artifacts SET content_hash='{forged_hash}' WHERE artifact_id=?1"),
            "UPDATE artifacts SET sensitivity='secret' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET retention_class='persistent' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET expires_at='2027-01-01T00:00:00Z' WHERE artifact_id=?1"
                .to_owned(),
            "UPDATE artifacts SET origin_kind='system' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET origin_task_id='T-forged' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET origin_program_hash='sha256:aaaa' WHERE artifact_id=?1"
                .to_owned(),
            "UPDATE artifacts SET origin_node_id='forged-node' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET origin_binding_id='forged-binding' WHERE artifact_id=?1"
                .to_owned(),
            "UPDATE artifacts SET origin_provider_id='forged-provider' WHERE artifact_id=?1"
                .to_owned(),
            "UPDATE artifacts SET integrity_state='pending' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET integrity_verifier='forged' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET labels_json='[\"forged\"]' WHERE artifact_id=?1".to_owned(),
            "UPDATE artifacts SET created_at='2027-01-01T00:00:00Z' WHERE artifact_id=?1"
                .to_owned(),
        ];
        for mutation in mutations {
            manager
                .connection
                .execute_batch("SAVEPOINT metadata_tamper")
                .unwrap();
            manager
                .connection
                .execute(&mutation, [&artifact.artifact_id])
                .unwrap();
            assert!(matches!(
                manager.import_artifact(&request, &mut PanicReader),
                Err(TaskManagerError::InvalidRecord(_))
            ));
            manager
                .connection
                .execute_batch("ROLLBACK TO metadata_tamper; RELEASE metadata_tamper")
                .unwrap();
        }

        let (sequence, previous_hash, original_event_json) = manager
            .connection
            .query_row(
                "SELECT sequence,previous_event_hash,event_json FROM provenance_events
                 WHERE task_id='T-artifact' AND event_type='artifact.imported'",
                [],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )
            .unwrap();
        manager
            .connection
            .execute_batch("DROP TRIGGER provenance_events_no_update")
            .unwrap();
        for mutation in [
            ("actor", json!({"kind":"user","id":"user:forged"})),
            ("schema_version", json!("9.9")),
            ("input_artifacts", json!(["artifact:forged"])),
            ("details.blob_reused", json!(true)),
        ] {
            manager
                .connection
                .execute_batch("SAVEPOINT import_event_tamper")
                .unwrap();
            let mut event: serde_json::Value = serde_json::from_str(&original_event_json).unwrap();
            if mutation.0 == "details.blob_reused" {
                event["details"]["blob_reused"] = mutation.1;
            } else {
                event[mutation.0] = mutation.1;
            }
            let event_json = canonical_json(&event).unwrap();
            let event_hash = provenance_hash(
                "T-artifact",
                u64::try_from(sequence).unwrap(),
                previous_hash.as_deref(),
                &event,
            )
            .unwrap();
            manager
                .connection
                .execute(
                    "UPDATE provenance_events SET event_json=?1,event_hash=?2
                     WHERE task_id='T-artifact' AND sequence=?3",
                    params![event_json, event_hash, sequence],
                )
                .unwrap();
            assert!(matches!(
                manager.import_artifact(&request, &mut PanicReader),
                Err(TaskManagerError::InvalidRecord(_))
            ));
            manager
                .connection
                .execute_batch("ROLLBACK TO import_event_tamper; RELEASE import_event_tamper")
                .unwrap();
        }
    }

    #[test]
    fn writer_admission_waits_for_durable_staging_entry_before_consuming_grant() {
        let temp = TempDir::new().unwrap();
        let mut manager = manager(&temp);
        let allocation_id = "alloc-staging-durability";
        let (binding_id, attempt_id) = install_one_shot_binding(
            &manager,
            "staging-durability",
            &[],
            &[("artifact.write", "output-allocation", allocation_id)],
        );
        let session = session_for_binding(&manager, "T-artifact", &binding_id);
        let mut request = allocation(allocation_id);
        request.binding_id = Some(binding_id);
        request.attempt_id = Some(attempt_id);
        manager
            .allocate_bound_artifact_output(&session, &request)
            .unwrap();
        let staging_ref = load_allocation_row(&manager.connection, allocation_id)
            .unwrap()
            .unwrap()
            .staging_ref
            .unwrap();
        WRITER_STAGING_DURABILITY_TEST_HOOK.with(|hook| {
            *hook.borrow_mut() = Some(Box::new(|| {
                Err(TaskManagerError::Io(std::io::Error::other(
                    "injected staging directory sync failure",
                )))
            }));
        });

        assert!(matches!(
            manager.open_bound_artifact_output(&session, allocation_id),
            Err(TaskManagerError::Io(_))
        ));
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT state FROM artifact_output_allocations WHERE allocation_id=?1",
                    [allocation_id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "ALLOCATED"
        );
        assert_eq!(
            manager
                .connection
                .query_row(
                    "SELECT uses_consumed FROM authority_grants
                     WHERE grant_id='grant-staging-durability-0'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        assert!(
            resolve_internal_ref(&manager.artifact_store_root, &staging_ref)
                .unwrap()
                .exists()
        );
        assert!(
            manager
                .open_bound_artifact_output(&session, allocation_id)
                .is_err()
        );
        manager.reconcile_artifacts_startup().unwrap();
        assert!(
            !resolve_internal_ref(&manager.artifact_store_root, &staging_ref)
                .unwrap()
                .exists()
        );
        assert!(
            manager
                .open_bound_artifact_output(&session, allocation_id)
                .is_ok()
        );
    }

    #[test]
    fn staging_open_each_invoked_failure_preserves_unconsumed_allocation() {
        for step in ["create_new", "permissions", "file_sync", "dir_sync"] {
            let temp = TempDir::new().unwrap();
            let mut manager = manager(&temp);
            let id = format!("alloc-open-fail-{step}");
            let (binding_id, attempt_id) = install_one_shot_binding(
                &manager,
                step,
                &[],
                &[("artifact.write", "output-allocation", &id)],
            );
            let mut request = allocation(&id);
            request.binding_id = Some(binding_id);
            request.attempt_id = Some(attempt_id);
            allocate_bound(&mut manager, &request);
            let staging_ref = load_allocation_row(&manager.connection, &id)
                .unwrap()
                .unwrap()
                .staging_ref
                .unwrap();
            let staging_path = manager.artifact_store_root.join(&staging_ref);
            let injected_path = staging_path.clone();
            STAGING_OPEN_INVOCATION_TEST_HOOK.with(|hook| {
                *hook.borrow_mut() = Some(Box::new(move |called| {
                    if called == step {
                        if step == "create_new" {
                            std::fs::write(&injected_path, b"partial private construction")?;
                        }
                        Err(TaskManagerError::Io(std::io::Error::other(
                            "injected primitive failure",
                        )))
                    } else {
                        Ok(())
                    }
                }));
            });
            assert!(manager.open_artifact_output(&id).is_err());
            STAGING_OPEN_INVOCATION_TEST_HOOK.with(|hook| {
                hook.borrow_mut().take();
            });
            let (state, uses, invoked, pending): (String, i64, i64, i64) = manager.connection.query_row(
                "SELECT a.state,g.uses_consumed,
                 (SELECT COUNT(*) FROM trusted_time_effect_resolutions r JOIN trusted_time_effect_preparations p USING(marker_id)
                  WHERE p.subject_id=a.allocation_id AND r.resolution_kind='EFFECT_INVOKED'),
                 (SELECT COUNT(*) FROM trusted_time_effect_pending x JOIN trusted_time_effect_preparations p USING(marker_id)
                  WHERE p.subject_id=a.allocation_id)
                 FROM artifact_output_allocations a JOIN authority_grants g ON g.task_id=a.task_id
                 WHERE a.allocation_id=?1 AND g.grant_id=?2",
                params![id, format!("grant-{step}-0")],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            ).unwrap();
            assert_eq!(state, "ALLOCATED");
            assert_eq!(uses, 0);
            assert!(invoked >= 1);
            assert_eq!(pending, 0);
            assert!(staging_path.exists());
            assert!(manager.open_artifact_output(&id).is_err());
            manager.reconcile_artifacts_startup().unwrap();
            assert!(!staging_path.exists());
        }
    }

    #[test]
    fn staging_open_unresolved_primitive_quarantines_allocated_residue_on_reopen() {
        for step in ["create_new", "permissions", "file_sync", "dir_sync"] {
            let temp = TempDir::new().unwrap();
            let mut manager = manager(&temp);
            let id = format!("alloc-open-pending-{step}");
            manager.allocate_artifact_output(&allocation(&id)).unwrap();
            let staging_ref = load_allocation_row(&manager.connection, &id)
                .unwrap()
                .unwrap()
                .staging_ref
                .unwrap();
            let staging_path = manager.artifact_store_root.join(&staging_ref);
            STAGING_OPEN_RESOLUTION_TEST_HOOK.with(|hook| {
                *hook.borrow_mut() = Some(Box::new(move |called| {
                    if called == step {
                        Err(TaskManagerError::Io(std::io::Error::other(
                            "injected resolution failure",
                        )))
                    } else {
                        Ok(())
                    }
                }));
            });
            assert!(manager.open_artifact_output(&id).is_err());
            STAGING_OPEN_RESOLUTION_TEST_HOOK.with(|hook| {
                hook.borrow_mut().take();
            });
            assert!(staging_path.exists());
            let seal_path = manager.artifact_store_root.join(seal_ref(&staging_ref));
            std::fs::write(&seal_path, b"unresolved seal residue").unwrap();
            let seal = manager
                .artifact_store_dir
                .open(safe_internal_ref(&seal_ref(&staging_ref)).unwrap())
                .unwrap();
            secure_cap_file_permissions(&seal).unwrap();
            let pending: i64 = manager.connection.query_row(
                "SELECT COUNT(*) FROM trusted_time_effect_pending x JOIN trusted_time_effect_preparations p USING(marker_id)
                 WHERE p.subject_kind='ARTIFACT_STAGING_WRITE' AND p.subject_id=?1",
                [&id], |row| row.get(0),
            ).unwrap();
            assert_eq!(pending, 1);
            drop(manager);
            let mut reopened = TaskManager::open_with_clock(
                temp.path().join("task-manager.sqlite"),
                Box::new(FixedClock),
            )
            .unwrap();
            assert_eq!(
                load_allocation_row(&reopened.connection, &id)
                    .unwrap()
                    .unwrap()
                    .state,
                "ALLOCATED"
            );
            assert!(staging_path.exists());
            assert_eq!(
                std::fs::read(&seal_path).unwrap(),
                b"unresolved seal residue"
            );
            assert!(reopened.open_artifact_output(&id).is_err());
        }
    }

    #[test]
    fn staging_open_rechecks_current_grant_before_every_primitive() {
        for step in ["create_new", "permissions", "file_sync", "dir_sync"] {
            let temp = TempDir::new().unwrap();
            let mut manager = manager(&temp);
            let id = format!("alloc-open-revoked-{step}");
            let (binding_id, attempt_id) = install_one_shot_binding(
                &manager,
                &format!("open-revoked-{step}"),
                &[],
                &[("artifact.write", "output-allocation", &id)],
            );
            let mut request = allocation(&id);
            request.binding_id = Some(binding_id);
            request.attempt_id = Some(attempt_id);
            allocate_bound(&mut manager, &request);
            let database = temp.path().join("task-manager.sqlite");
            let grant_id = format!("grant-open-revoked-{step}-0");
            let target_invocations = Arc::new(AtomicUsize::new(0));
            let invoked = Arc::clone(&target_invocations);
            STAGING_OPEN_INVOCATION_TEST_HOOK.with(|hook| {
                *hook.borrow_mut() = Some(Box::new(move |called| {
                    if called == step {
                        invoked.fetch_add(1, Ordering::SeqCst);
                    }
                    Ok(())
                }));
            });
            STAGING_OPEN_BEFORE_ENTRY_TEST_HOOK.with(|hook| {
                *hook.borrow_mut() = Some(Box::new(move |called| {
                    if called == step {
                        Connection::open(&database)?.execute(
                            "UPDATE authority_grants SET state='REVOKED',revoked_at='2026-09-19T22:00:00Z' WHERE grant_id=?1",
                            [&grant_id],
                        )?;
                    }
                    Ok(())
                }));
            });
            assert!(manager.open_artifact_output(&id).is_err());
            STAGING_OPEN_BEFORE_ENTRY_TEST_HOOK.with(|hook| {
                hook.borrow_mut().take();
            });
            STAGING_OPEN_INVOCATION_TEST_HOOK.with(|hook| {
                hook.borrow_mut().take();
            });
            assert_eq!(target_invocations.load(Ordering::SeqCst), 0);
            let (uses, no_effect, pending): (i64, i64, i64) = manager.connection.query_row(
                "SELECT g.uses_consumed,
                 (SELECT COUNT(*) FROM trusted_time_effect_resolutions r JOIN trusted_time_effect_preparations p USING(marker_id)
                  WHERE p.subject_id=?1 AND r.resolution_kind='NO_EFFECT'),
                 (SELECT COUNT(*) FROM trusted_time_effect_pending x JOIN trusted_time_effect_preparations p USING(marker_id)
                  WHERE p.subject_id=?1)
                 FROM authority_grants g WHERE g.grant_id=?2",
                params![id, format!("grant-open-revoked-{step}-0")],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            ).unwrap();
            assert_eq!((uses, no_effect, pending), (0, 1, 0));
            assert_eq!(
                load_allocation_row(&manager.connection, &id)
                    .unwrap()
                    .unwrap()
                    .state,
                "ALLOCATED"
            );
        }
    }

